  4404  #define STRNCMP(a,b,n) (strncasecmp((a),(b),(n)) || strlen(a)!=(n))
  4405  int bam_str2flag(const char *str)
  4406  {
  4407      char *end, *beg = (char*) str;
  4408      long int flag = strtol(str, &end, 0);
  4409      if ( end!=str ) return flag;    // the conversion was successful
  4410      flag = 0;
  4411      while ( *str )
  4412      {
  4413          end = beg;
  4414          while ( *end && *end!=',' ) end++;
  4415          if ( !STRNCMP("PAIRED",beg,end-beg) ) flag |= BAM_FPAIRED;
  4416          else if ( !STRNCMP("PROPER_PAIR",beg,end-beg) ) flag |= BAM_FPROPER_PAIR;
  4417          else if ( !STRNCMP("UNMAP",beg,end-beg) ) flag |= BAM_FUNMAP;
  4418          else if ( !STRNCMP("MUNMAP",beg,end-beg) ) flag |= BAM_FMUNMAP;
  4419          else if ( !STRNCMP("REVERSE",beg,end-beg) ) flag |= BAM_FREVERSE;
  4420          else if ( !STRNCMP("MREVERSE",beg,end-beg) ) flag |= BAM_FMREVERSE;
  4421          else if ( !STRNCMP("READ1",beg,end-beg) ) flag |= BAM_FREAD1;
  4422          else if ( !STRNCMP("READ2",beg,end-beg) ) flag |= BAM_FREAD2;
  4423          else if ( !STRNCMP("SECONDARY",beg,end-beg) ) flag |= BAM_FSECONDARY;
  4424          else if ( !STRNCMP("QCFAIL",beg,end-beg) ) flag |= BAM_FQCFAIL;
  4425          else if ( !STRNCMP("DUP",beg,end-beg) ) flag |= BAM_FDUP;
  4426          else if ( !STRNCMP("SUPPLEMENTARY",beg,end-beg) ) flag |= BAM_FSUPPLEMENTARY;
  4427          else return -1;
  4428          if ( !*end ) break;
  4429          beg = end + 1;
  4430      }
  4431      return flag;
  4432  }
